const input = $input.first().json.output;

// Fonction pour extraire une section
function extractSection(text, sectionName, nextSection = null) {
  const regex = new RegExp(`${sectionName}\\s*:\\s*\\n?([\\s\\S]*?)(?=${nextSection ? nextSection + '\\s*:' : '$'})`, 'i');
  const match = text.match(regex);
  return match ? match[1].trim() : '';
}

// Extraire les sections
const titre = extractSection(input, 'Titre', 'Description');
const description = extractSection(input, 'Description', 'Ingrédients');
const ingredientsRaw = extractSection(input, 'Ingrédients', 'Recette');
const recetteRaw = extractSection(input, 'Recette', 'Nutrition');
const nutritionRaw = extractSection(input, 'Nutrition', 'Tags');
const tagsRaw = extractSection(input, 'Tags');

// Parser les ingrédients
let ingredients = [];
try {
  ingredients = JSON.parse(ingredientsRaw);
} catch (error) {
  ingredients = [];
}

// Parser la nutrition
let nutrition = {};
try {
  nutrition = JSON.parse(nutritionRaw);
} catch (error) {
  nutrition = {};
}

// Parser les tags
let tags = [];
try {
  const cleaned = tagsRaw.replace(/\n/g, ' ').trim();
  tags = JSON.parse(cleaned);
} catch {
  const cleaned = tagsRaw.replace(/[\[\]]/g, '').trim();
  tags = cleaned ? cleaned.split(',').map(t => t.trim()).filter(Boolean) : [];
}

// Parser les étapes de la recette
const recetteSteps = recetteRaw
  .split('\n')
  .filter(line => /^\d+\./.test(line.trim()))
  .map(line => line.replace(/^\d+\.\s*/, '').trim());

return {
  titre,
  description,
  ingredients: JSON.stringify(ingredients),
  recette: JSON.stringify(recetteSteps),
  calories: nutrition.calories || 0,
  proteines: nutrition.proteines || 0,
  glucides: nutrition.glucides || 0,
  lipides: nutrition.lipides || 0,
  tags
};

